String readLine(InputStream r) throws IOException {
    StringBuilder b = new StringBuilder();
    int c;
    while ((c = r.read()) != -1) {
        if (c == '\n') break;
        b.appendCodePoint(c);
    }
    if (b.codePointAt(b.length() -1) == '\r') {
        b.delete(b.length() -1, b.length());
    }

