          fullRotationBrightnessIncreaseAndCenterCropResultBitmap,
          testId);
  assertThat(averagePixelAbsoluteDifference).isAtMost(MAXIMUM_AVERAGE_PIXEL_ABSOLUTE_DIFFERENCE);
}

